  /**
   * Test ProtoRuntime {@link ProtoRuntime#parseDelimitedFrom(InputStream)} with
   * {@code input}.
   * <p>
   * Method under test:
   * {@link DeviceInfoProtos.ProtoRuntime#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test ProtoRuntime parseDelimitedFrom(InputStream) with 'input'")
  void testProtoRuntimeParseDelimitedFromWithInput2() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));
    when(input.read()).thenReturn(1);

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class, () -> DeviceInfoProtos.ProtoRuntime.parseDelimitedFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(1));
    verify(input).read();
  }

