  @Test
  @DisplayName("Test ProtoRuntime parseFrom(byte[], ExtensionRegistryLite) with 'byte[]', 'ExtensionRegistryLite'")
  void testProtoRuntimeParseFromWithByteExtensionRegistryLite2() throws InvalidProtocolBufferException {
    // Arrange and Act
    DeviceInfoProtos.ProtoRuntime actualParseFromResult = DeviceInfoProtos.ProtoRuntime
        .parseFrom(new byte[]{18, 6, 'A', 'X', 'A', 'X', 'A', 'X'}, ExtensionRegistryLite.getEmptyRegistry());

    // Assert
    assertEquals(1, actualParseFromResult.getAllFields().size());
    List<Integer> messageCountersList = actualParseFromResult.getMessageCountersList();
    assertEquals(6, messageCountersList.size());
    assertEquals(6, actualParseFromResult.getMessageCountersCount());
    assertEquals(65, messageCountersList.get(0).intValue());
    assertEquals(65, messageCountersList.get(2).intValue());
    assertEquals(65, messageCountersList.get(4).intValue());
    assertEquals(8, actualParseFromResult.getSerializedSize());
    assertEquals(88, messageCountersList.get(1).intValue());
    assertEquals(88, messageCountersList.get(3).intValue());
    assertEquals(88, messageCountersList.get(5).intValue());
    List<Integer> runtimeErrorsList = actualParseFromResult.getRuntimeErrorsList();
    assertTrue(runtimeErrorsList.isEmpty());
    Descriptors.Descriptor descriptorForType = actualParseFromResult.getDescriptorForType();
    assertEquals(DeviceInfoProtos.ProtoRuntime.RUNTIME_ERRORS_FIELD_NUMBER, descriptorForType.getFields().size());
    DescriptorProtos.FileDescriptorProto toProtoResult = descriptorForType.getFile().toProto();
    DescriptorProtos.FileDescriptorProto defaultInstanceForType = toProtoResult.getDefaultInstanceForType();
    assertSame(runtimeErrorsList, defaultInstanceForType.getPublicDependencyList());
    assertSame(runtimeErrorsList, toProtoResult.getPublicDependencyList());
    assertSame(runtimeErrorsList, defaultInstanceForType.getWeakDependencyList());
    assertSame(runtimeErrorsList, toProtoResult.getWeakDependencyList());
    DeviceInfoProtos.ProtoRuntime defaultInstanceForType2 = actualParseFromResult.getDefaultInstanceForType();
    assertSame(runtimeErrorsList, defaultInstanceForType2.getMessageCountersList());
    assertSame(runtimeErrorsList, defaultInstanceForType2.getRuntimeErrorsList());
  }

