  /**
   * Test ProtoUpdateInfo {@link ProtoUpdateInfo#parseDelimitedFrom(InputStream)}
   * with {@code input}.
   * <p>
   * Method under test:
   * {@link DeviceInfoProtos.ProtoUpdateInfo#parseDelimitedFrom(InputStream)}
   */
  @Test
  @DisplayName("Test ProtoUpdateInfo parseDelimitedFrom(InputStream) with 'input'")
  void testProtoUpdateInfoParseDelimitedFromWithInput2() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));
    when(input.read()).thenReturn(1);

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class,
        () -> DeviceInfoProtos.ProtoUpdateInfo.parseDelimitedFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(1));
    verify(input).read();
  }

